: [{"label": "Focus on the key idea", "text": "Interpret a ratio as a comparison of quantities. A ratio of two red counters to three blue counters means each matching group contains two red and three blue."}], "quickCheck": {"prompt": "What does red to blue of 2:3 mean?", "options": ["Two red for every three blue", "Three red for every two blue"], "correctIndex": 0, "explanation": "Two red for every three blue. A ratio states the relative amounts of two quantities. A ratio of two red counters to three blue counters means each matching group contains two red and three blue."}}}, {"title": "Order and units", "block_type": "relationships", "sequence": 1, "objective": "Identify the order and units of a ratio", "required": true, "content": {"body": "The order in a ratio matters: girls to boys is different from boys to girls. Convert measurements to the same units before simplifying a ratio of lengths.", "competencyKeys": ["foundation-2"], "prerequisites": [], "modes": [{"label": "Focus on the key idea", "text": "Identify the order and units of a ratio. Convert measurements to the same units before simplifying a ratio of lengths."}], "quickCheck": {"prompt": "A class has 12 girls and 8 boys. What is girls to boys?", "options": ["8:12", "12:8"], "correctIndex": 1, "explanation": "12:8. The order in a ratio matters: girls to boys is different from boys to girls. Convert measurements to the same units before simplifying a ratio of lengths."}}}, {"title": "Equivalent ratios", "block_type": "relationships", "sequence": 2, "objective": "Recognise and simplify equivalent ratios", "required": true, "content": {"body": "Multiply or divide every part of a ratio by the same positive factor to keep the comparison. The ratio 4:6 simplifies to 2:3 by dividing both parts by two.", "competencyKeys": ["foundation-3"], "prerequisites": [], "modes": [{"label": "Focus on the key idea", "text": "Recognise and simplify equivalent ratios. The ratio 4:6 simplifies to 2:3 by dividing both parts by two."}], "quickCheck": {"prompt": "Which ratio is equivalent to 4:6?", "options": ["2:3", "2:4"], "correctIndex": 0, "explanation": "2:3. Multiply or divide every part of a ratio by the same positive factor to keep the comparison. The ratio 4:6 simplifies to 2:3 by dividing both parts by two."}}}, {"title": "Parts and whole", "block_type": "relationships", "sequence": 3, "objective": "Distinguish part-to-part and part-to-whole comparisons", "required": true, "content": {"body": "In a red-to-blue ratio of 2:3, there are five parts altogether. Red is two parts out of five of the total, rather than two out of three.", "competencyKeys": ["foundation-4"], "prerequisites": [], "modes": [{"label": "Focus on the key idea", "text": "Distinguish part-to-part and part-to-whole comparisons. Red is two parts out of five of the total, rather than two out of three."}], "quickCheck": {"prompt": "In a red-to-blue ratio of 2:3, what fraction of all counters is red?", "options": ["Two thirds", "Two fifths"], "correctIndex": 1, "explanation": "Two fifths. In a red-to-blue ratio of 2:3, there are five parts altogether. Red is two parts out of five of the total, rather than two out of three."}}}, {"title": "Scale both parts", "block_type": "misconception", "sequence": 4, "objective": "Correct additive scaling misconceptions", "required": true, "content": {"body": "Equivalent ratios use multiplication, not the same addition to each number. Doubling 2:3 gives 4:6; adding two gives 4:5 and changes the comparison.", "competencyKeys": ["foundation-5"], "prerequisites": [], "modes": [{"label": "Focus on the key idea", "text": "Correct additive scaling misconceptions. Doubling 2:3 gives 4:6; adding two gives 4:5 and changes the comparison."}], "quickCheck": {"prompt": "To double the mixture described by 2:3, which ratio should be used?", "options": ["4:6", "4:5"], "correctIndex": 0, "explanation": "4:6. Equivalent ratios use multiplication, not the same addition to each number. Doubling 2:3 gives 4:6; adding two gives 4:5 and changes the comparison."}}}, {"title": "Share in a ratio", "block_type": "application", "sequence": 5, "objective": "Use a simple ratio to share a quantity", "required": true, "content": {"body": "To share ten exercise books in the ratio 2:3, first count five total parts. Each part is two books, so the shares are four books and six books.", "competencyKeys": ["foundation-6"], "prerequisites": [], "modes": [{"label": "Focus on the key idea", "text": "Use a simple ratio to share a quantity. Each part is two books, so the shares are four books and six books."}], "quickCheck": {"prompt": "Ten books are shared in the ratio 2:3. What is the smaller share?", "options": ["Two books", "Four books"], "correctIndex": 1, "explanation": "Four books. To share ten exercise books in the ratio 2:3, first count five total parts. Each part is two books, so the shares are four books and six books."}}}]}, {"slug": "percentages", "concept_type": "quantitative", "competencies": [{"depth": "foundation", "key": "foundation-1", "description": "Explain percent as parts per hundred", "evidence_type": "quick_check", "sequence": 0}, {"depth": "foundation", "key": "foundation-2", "description": "Connect percentages to fractions and decimals", "evidence_type": "quick_check", "sequence": 1}, {"depth": "foundation", "key": "foundation-3", "description": "Find a simple percentage of a quantity", "evidence_type": "quick_check", "sequence": 2}, {"depth": "foundation", "key": "foundation-4", "description": "Identify the whole used in a percentage", "evidence_type": "quick_check", "sequence": 3}, {"depth": "foundation", "key": "foundation-5", "description": "Correct percent and percentage-point misconceptions", "evidence_type": "misconception", "sequence": 4}, {"depth": "foundation", "key": "foundation-6", "description": "Interpret a percentage in a practical situation", "evidence_type": "application", "sequence": 5}, {"depth": "applied", "key": "applied-1", "descriptio